P('ethical-split','可理解的复仇与不可抵销的行为代价',['assault','principle','sunhunt'],['呈受害线索但不编全知案卷','让复仇者主动选择组织/方法','分别记录援敌及无辜代价','局部合作不等永久洗白或司法结案'],'多方组织/复仇故事','让受害者沉默只为男人升级或以暴制暴当法律结果','重造受害者声音、程序/修复与利益，不复用原罪案细节')
P('specific-counter','前所得辅助能力回收为多人克制链',['waves','sunhunt','return'],['先显示敌优势真有效','前场取得有边界的辅助资源','后战将禁疗/限制/破免/接应拆给多人','得胜后仍记录成员代价和限制'],'团队战需要区分职业/人物贡献','后加无前证万能钥匙或只主独得所有功能','重建原创规则矩阵与团队互赖，替换技能名和数值')
P('changed-wave','每轮改变问题，避免只堆敌数量',['waves','thunder','ladder','dragons'],['由地底/扇面/合波/墙等改变空间','重排T/治疗/工匠与友伤模式','写实际名额/地形损耗','以一次确败显层级边界'],'连续大战/副本','重复清小怪领奖再清小怪无新抉择','每轮只保一个独特的决策问题与不可逆后果')
P('god-tier','晋升拆成身份、资格、能力与验证',['award','godhood','supplies','dihai'],['先得称号但技能不可用','取得额外资格或资源','实学/实测确认可行动','更强对手仍逼失败重试'],'升级文能力系统','每升一阶自动跨一切强敌导致先前规则消失','另造非等级型晋升及可观察试验，避免复制神格表')
P('partner-cost','旅途中伙伴从误认替身转成互救者',['aosave','spider','sulun','dihai','return'],['错误希望带入新伙伴','失望后仍选择救她','给她关键救援/知识/牺牲决定','用背负与落脚回报她的成本'],'寻找目标时引入独立支线人物','把新伙伴只当情报机或最后牺牲工具','重造她的过去/目的/拒绝及与主不同的选择，不复制奥丹旧史')
P('environment-limit','环境克制可迫退而非一次解决敌人',['army','bloodsea','marriage'],['先正面失败确认差距','观察可利用地形/材料','环境只产生有限胜机或相持','再由新资源与协作完成后战'],'强敌超过主常规输出上限','把幸运环境写主事前全知或一次漏洞通吃','设计可验证、会耗损、敌可应对的原创环境规则')
P('small-gesture','微小动作延迟解释但确有回收',['beast','return'],['先给可见但未解释的准备动作','后用同一物/坐标的行动回验','角色补说明因果','保当初读者与角色知道的差别'],'逃生/复杂计划伏笔','只有后来口称早准备而原场毫无动作','原创物理/制度资源与预留成本，不搬神石与轻踏')
P('mission-not-person','系统任务成与人物目标不必同成',['mission','fall','award','dream'],['分别列系统条件/委托目的/人物愿望','让可见结算只答其中一项','揭委托背后的控制欲或仍失人','下一阶段承接未完成私人目标'],'任务制剧情/经营主线','拿一条完成公告洗掉所有死亡或伦理失败','重新设计相互不一致的目标、奖励与被救者自主选择')
P('ordinary-foundation','让工匠、补给与普通队伍成为英雄行动前提',['scales','ladder','supplies','dihai'],['先写产能/准备/运输','普通成员付伤亡或劳动','英雄获得窗口而非凭空抵达','在奖励/后续关系中留账'],'大规模组织战/远征','人数仅炫战损无后续，普通人都无主体','重造后勤职业与可追踪的人员后果，控制数字密度')
P('endpoint-shift','大救援兑现后转为认知与身份问题',['beijing','cage','return','dream'],['提前给现实身份任务','充分完成找人/救出/返界动作','回归后恢复沟通与照护','在被救者回应前切口而非假装全结局'],'卷末需既满足又开启新问题','所有答案推迟无任何兑现或用哭强定唯一含义','原创另一种身份冲突/责任，保具体已成与未答的清单')

dimensions={k:[] for k in ['worldbuilding','characters','plot','style','narrative','dialogue','pacing','themes','continuity']}
def D(k,title,fact,inference,refs):dimensions[k].append(dict(title=title,fact=fact,inference=inference,claim_kind='synthesis',evidence=E(refs)))
D('worldbuilding','神位不是一次挂牌全功能','修罗初成三技仍灰；1462龙吐晶凝格后三灰技即激活；1464九转另学狂神冲撞；普通250飞升另低率至255。','把资格与可用行动拆开能留晋升过程；本书概率不依主猜补数。',[1460,1461,1462,1464,1472])
D('worldbuilding','超常层级仍有规则切面','血颅100%魔免却物战可伤、苏伦神级免神临但断臂减攻/体内紫啸可杀，帝海先逼败再重战。','战力要按免疫对象、前摇、地形与资源读，不能从一个词推绝对无敌。',[1403,1404,1483,1484,1491,1492])
D('worldbuilding','组织成长经过产能与交付','1128鳞已交而后仅345成甲，火套30真穿；招幸运有一月观察与训练配额；斩铁八周合同仅首批已用。','宏观数字能参与行动约束；计划、资格、库存、实交、实际装备分层才有经营感。',[1339,1341,1376,1382,1409,1436])
D('worldbuilding','领域规则有范围与例外','不死境禁游戏通讯/返生、死亡-20和幸损，论坛仍能PM；远征禁复中弓绝处逢生明确例外。','限制规则不应被泛化成全媒介/全地图；例外需实际来源而非研究者救场。',[1393,1427,1468,1472,1504])
D('worldbuilding','现实科技解释仍属于本书情境','主亲见现实昏睡董欣然；徐解释造脑七年/游戏真实心理/脑波峰将醒，自称无权限定位。','情境借技术打开双世界身份，不构成现实医学或主脑事实证明；实体见证与因果解释不同层。',[1500,1504])
D('characters','主行动有伦理择弃也有盲点','拒刷盟友/真放卓洛、背奥不弃；砸欧车、酷刑逼魂工、偷Boss与偏会分盾亦在。','研究不应从强救人行动将主净化成无缺道德代言；冲突中保责任才有可分析性。',[1298,1398,1445,1469,1470,1492,1504])
D('characters','女性从被救到反向救人','心失腿受治又囚中助杀夜/开裂；奥初误认对象后多次箭救与蛊冰巨；月脱险后禁疗助围阳。','受伤不是能力取消，双向因果可抵抗单一奖品化，但叙述仍有男性凝视局限。',[1313,1443,1475,1483,1492,1503,1504])
D('characters','亲密关系有明确等待与否认','林主到临门停、约一年正常再；连说自己北不是主的女人；何主床亲密被明断无圆房。','同床、亲吻、玩笑和未回应爱慕不能当同一种关系状态；拒绝/自述要与动作并读。',[1319,1322,1463,1476])
D('characters','复仇者可理解但不免行为债','猪因婉受害指控离炼狱建暗佣，又帮北境杀俄玩家；主保灭神与其对战，后暂联夺镇天。','多动机人物的阶段合作不等洗白或永结盟，受害不代当事人获得司法/康复结论。',[1372,1376,1384,1385,1420,1442,1444])
D('characters','强NPC也有损伤/权限/误认','卡新神仍被雷伤；冰亲承刚才短控/说杀不了圣；苏重伤开不了门；书无权查主脑。','这些可见限制使玩家与NPC协作有必要，不能以头衔把他们扩成全知全能。',[1425,1455,1457,1458,1463,1466])
D('plot','任务完成与私人失落错位','混乱远征正式完成/MVP时心落深渊未确存死；最终游戏带回又未现实醒。','奖励闭环与情感未闭环交叉驱动后段，无需撤销已经兑现的成功。',[1459,1460,1461,1500,1504])
D('plot','所有权链改变战略收益','周买鞭后被爆/主追回归还；金令售后被离偷/主退款；赤臂第一次锁没爆第二次才猪夺。','追踪人物、物、钱各自状态能产生多方剧情，不能只跟主杀数。',[1302,1303,1310,1335,1336,1337,1363,1431,1432])
D('plot','新辅助物回收为具体难题解法','月光先得凄冷杖，围阳时主特召其禁疗；神石先掉入包，百兽轻踏后逆阵返七。','有同一能力/同一物后用的才可称铺垫兑现；其他相似机制仅互照。',[1420,1443,1444,1493,1495,1503])
D('plot','误认有修正也有残余未知','早心少女误成奥/仍救；苏伦言心已死被奥当地判断保留并后亲见活否定；蒂雅未知未再给结论。','不把每个早未知当卷末未知，也不把未再现人物自动判死，终点需要重新匹配。',[1425,1475,1483,1503,1504])
D('plot','现实受害引爆组织改属','月救出促虎归古剑/烛宣战；婉酒席事件使猪断雇佣转北境暗佣。','现实关系与线上利益互推有具体桥，但第二案见闻层比第一案更受限。',[1312,1315,1324,1372,1375,1376])
D('style','第一人称数值快感兼口语夸张','面板、爆伤、百万战损和IMBA等惊叹密集；主口称不可能/必然常被下一场失败缩限。','可学让数据改变抉择的快感，不宜把所有夸词当规则或等量移植表格。',[1339,1407,1423,1465,1491,1492])
D('style','生活物件落在宏大场间','父家西红柿炒鸡蛋、林备套/抱睡、饭局石剪布，和龙心/亡魂/世界城战交错。','具体物件减轻抽象高阶力量的漂浮感；亲密物件仍需保成年与未发生事实边界。',[1318,1322,1342,1408,1487])
D('style','强身体感承担情绪而非只标签','紫鳞灼痛/紫血与晕、奥背上呼吸、心腿血/主破指甲和剑耐耗尽。','感官与工具损耗让照护可见，比直接说爱更能接入因果，但不可猎奇放大受害细节。',[1316,1317,1492,1493,1503])
D('style','戏谑与严肃切换有局限','明月侍寝暗箱被拒、酒局玩笑迅切强制与哭，神战损伤后仍有胸围/性玩笑。','轻重交错能提活力，也可能压低受害主体或让悲痛太快过去；不自动继承为用户风格。',[1370,1371,1372,1434,1454])
D('style','作者直接纠错也是源的一层','1440作者明说阳墨麒麟为笔误实踏云魔豹，正文仍保过往；等级/技能冷却另有未纠冲突。','明确纠错与研究猜错区别保存，不能把所有源冲突悄悄修平。',[1411,1416,1440,1460,1461])
D('narrative','读者比主早知爱语','冰战1455心说爱主因弱时互护、主在远处未听；1459携林坠前才对主明说爱。','同一情感两次陈述面向不同受众，构成戏剧反差而非重复告白等时生效。',[1455,1459])
D('narrative','视野外战用报告不假全知','猪挑战结果从林手机网页得；诸城收复和奥佩罗死/绝风由论坛伙伴说；主未亲看全程。','有限视角能扩大世界，但研究必须标来源且不补战术/末杀镜头。',[1435,1486,1499])
D('narrative','误读由可见动作推翻','心试行后撒娇不证原伤假；奥头歪主以为死、她立说没死；飞银被林挡后又伤活现。','第一人称早判断不等叙述事实，反证到来需保原误认与修正链。',[1311,1492,1493,1496,1497])
D('narrative','微动作延迟释义','1495轻踏地面只说准备，1503逆神石并由奥说预印。','前动作与后解释共同足以回收，不能把当章读者已懂写入知识表。',[1493,1495,1503])
D('narrative','双世界揭示分两次接收','1500主见现实少女/徐解释；1504心才听主谈现实便哭切断。','主与读者先知、当事人未完整回应形成新知情差；哭因不能唯一化。',[1500,1504])
D('dialogue','意愿以当事人话决定救援方向','月明确想离/哭求，公主说保族与佯婚，女醒拒父跟紫走。','对象有自己的目标才使救援不只是主的力量展示；来源缺失处不代受害者说完。',[1313,1346,1368,1501,1502])
D('dialogue','承诺带条件比空誓可核','主林一年正常再、爸多陪/买别墅、英八周每周12500、冰3—5年成龙。','条件、期限、数量赋予后证匹配标准，终点仍不能因真心就判履行。',[1319,1342,1343,1376,1467])
D('dialogue','敌人指控与求生话不能直接证实','苏伦心死/羞辱被后证否，寒揭苏旧恶她说忘了；夜许不争即自露围谷。','对话能暴露权力和矛盾，可信度取决利益/后行动，不是越详细越史实。',[1429,1483,1502,1503])
D('dialogue','正式公告与口述规则不完全同','死亡挑战早称拒掉会级，后正式公告拒-5/掉装备；百品晶官方低率与主猜概率。','至少同时存两来源，不擅择字面拼出新规则；实际胜负仅后证。',[1376,1432,1435,1472])
D('dialogue','调停完成行动不等完成追责','神舞调停让月离、烛承失管同时宣十倍报；李找黄局旧案仅请求。','对话有即时解围功能也可保组织矛盾，不能把和气离场洗成责任已清。',[1314,1315])
D('pacing','长战组块中更换约束','黄金混战围令转，远征前资源/Boss/要塞/多波/神战/内城逐换问题。','长篇规模可以由问题切换承载，重复战斗若只数更大则应压缩。',[1335,1336,1390,1402,1416,1425,1447])
D('pacing','强冲突后给可完成生活行动','七局赛后父家饭、血颅后午休三小时、深渊几日蒙太奇后赴京。','日常回气明确花时间/改关系，非无条件暂停世界威胁。',[1341,1342,1408,1498,1499])
D('pacing','两次败退防止后段线性碾压','雷鸣强攻逼玩家退/NPC真死，主神成后帝海初战仍败。','能力增长与上限重新暴露交替，重试必须有新方案/代价。',[1423,1425,1426,1465,1491,1492])
D('pacing','重复寻人保进展也有空耗','每层常问心位置但新图/奥/旧师/七层证词持续更新；四至七日只概述清怪而未逐场。','地图推进与知识推进配对可抵反复问讯疲劳，蒙太奇不能冒充逐场详描。',[1474,1475,1483,1495,1498])
D('pacing','结尾兑现追逐后立即转内心','破笼/逆阵/七到一逃/冰接应充分完成，最后房间谈另一世界而哭。','动作高潮有可见成果，再用认知悬念收束；不必取消前成功来悬空。',[1503,1504])
D('themes','不负同伴通过成本而非口号','主不刷可信盟友、实际背奥多日、耗油破笼；队友采药/冰开门/心破界同样行动。','互护由多方向劳动构成，主最后不是唯一救赎者。',[1298,1466,1467,1492,1503,1504])
D('themes','组织权力不应吞个人自主','月要离、婉被代言风险、公主佯婚保族、瑟琳娜拒父冥婚。','主题冲突在“为她好”的控制与她本人选择之间；研究需补记文本沉默而非替说。',[1313,1368,1372,1408,1501])
D('themes','公共胜利不能抵私人损伤','远征系统成但心坠、斯灭/蒂未知；救回游戏身不等现实醒。','多个价值账并存给长线重量，避免冠军式结局吞代价。',[1426,1459,1461,1504])
